const D = { energy:.72, density:.5, strike:.6, branch:.5, speed:1, scale:1, hue:275, x:.5, y:.5, style:'storm', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const st = P.style;
const clp = (v,a,b)=>Math.max(a,Math.min(b,v));
const intn = (K.intensity!=null?K.intensity:.6);
const sec = K.section||0;
const aMul = P.alpha/100;

// deterministic per-bolt offset (independent of restrike index)
const frb = i => { const s = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return s - Math.floor(s); };
// mulberry32 seeded PRNG for a single strike geometry
function mul(a){ return function(){ a|=0; a=a+0x6D2B79F5|0; let t=Math.imul(a^a>>>15,1|a); t=t+Math.imul(t^t>>>7,61|t)^t; return ((t^t>>>14)>>>0)/4294967296; }; }

// ---- style palettes ----
function skyPal(){
  if(st==='crimson')     return [356,62,12];
  if(st==='ice-blue')    return [208,62,14];
  if(st==='toxic-green') return [128,55,12];
  if(st==='blueprint')   return [212,52,15];
  return [258,60,15]; // storm
}
// gw=glow-width mult, cb=core-brightness mult, buzz=extra flicker (rendering philosophy per style)
function boltPal(){
  if(st==='crimson')     return {gH:8,   gS:88, cH:26,  cS:20, fH:12,  gw:1.5, cb:0.72, buzz:0.10}; // smouldering ember, wide diffuse glow, dim core
  if(st==='ice-blue')    return {gH:196, gS:82, cH:200, cS:10, fH:198, gw:0.75,cb:1.15, buzz:0.05}; // crisp, thin sharp glow, blazing white core
  if(st==='toxic-green') return {gH:96,  gS:92, cH:88,  cS:22, fH:100, gw:0.95,cb:0.95, buzz:0.35}; // buzzing acid veins, heavy flicker
  if(st==='blueprint')   return {gH:196, gS:46, cH:196, cS:40, fH:200, gw:1.0, cb:1.0,  buzz:0.0};  // flat schematic
  return {gH:(P.hue+sec*6)%360, gS:72, cH:(P.hue+30)%360, cS:14, fH:P.hue, gw:1.0, cb:1.0, buzz:0.08}; // storm
}

// ---- dim storm sky (cached buffer) ----
function buildSky(){
  const g = S.sky; g.colorMode(HSB,360,100,100,100); g.noStroke();
  const c = skyPal();
  const R = mul((P.seed*2654435761 ^ 0x9E37)>>>0);
  const bands = 46;
  for(let b=0;b<bands;b++){ const v=b/bands;
    const horizon = Math.exp(-Math.pow((v-0.66)/0.26,2));
    const bri = c[2]*(0.5 + 0.95*horizon);
    g.fill(c[0], c[1]*(1-0.18*horizon), bri);
    g.rect(0, v*g.height-1, g.width, g.height/bands+2);
  }
  for(let k=0;k<16;k++){ const cx=R()*g.width, cy=(0.12+R()*0.62)*g.height, rr=g.width*(0.12+R()*0.24);
    const lift = R()<0.5?1:-1;
    g.fill((c[0]+lift*8+360)%360, c[1]*0.8, clp(c[2]*(1+lift*0.55),0,100), 12);
    g.ellipse(cx,cy, rr*2, rr*1.1);
  }
  const dc=g.drawingContext; dc.save();
  const rg=dc.createRadialGradient(g.width/2,g.height*0.55,g.width*0.18, g.width/2,g.height*0.55,g.width*0.78);
  rg.addColorStop(0,'rgba(0,0,0,0)'); rg.addColorStop(1,'rgba(0,0,0,0.45)');
  dc.fillStyle=rg; dc.fillRect(0,0,g.width,g.height); dc.restore();
}

// ---- recursive-fork bolt generator -> array of {pts,gen} polylines ----
function genBolt(rnd, sx, sy){
  const strokes=[];
  const cnt={n:0};
  const cap = 10 + Math.round(P.branch*7);
  const spread = 0.26 + P.scale*0.14;
  const maxDepth = 1 + Math.round(P.branch*3);
  const forkP = 0.05 + P.branch*0.16;
  const step = u*(0.05 + P.scale*0.022);
  const mainLen = height*0.92 + u*0.05;
  function grow(x,y, dx,dy, len, depth, gen){
    if(cnt.n>cap) return;
    cnt.n++;
    const steps = Math.max(3, Math.round(len/step));
    const poly=[[x,y]];
    let px=x, py=y, ddx=dx, ddy=dy;
    const sl = len/steps;
    for(let s=0;s<steps;s++){
      const ang=(rnd()-0.5)*spread;
      const co=Math.cos(ang), sn=Math.sin(ang);
      let nx=ddx*co-ddy*sn, ny=ddx*sn+ddy*co;
      ny += 0.07*(depth===0?1:0.4); // downward bias, strongest on trunk
      const m=Math.hypot(nx,ny)||1; ddx=nx/m; ddy=ny/m;
      px+=ddx*sl; py+=ddy*sl;
      poly.push([px,py]);
      if(depth<maxDepth && cnt.n<cap && rnd()<forkP){
        const side = rnd()<0.5?1:-1;
        const ba = (0.45+rnd()*0.75)*side;
        const bc=Math.cos(ba), bs=Math.sin(ba);
        const bdx=ddx*bc-ddy*bs, bdy=ddx*bs+ddy*bc;
        grow(px,py, bdx,bdy, len*(0.34+rnd()*0.26), depth+1, gen+1);
      }
    }
    strokes.push({pts:poly, gen});
  }
  grow(sx,sy, 0,1, mainLen, 0, 0);
  return strokes;
}

// ---- (re)build size/seed/style-keyed caches ----
const skyKey = width+'x'+height+'|'+P.seed+'|'+st;
if(!S.sky || S.skyKey!==skyKey){
  if(S.sky && S.skyBufKey!==width+'x'+height){ S.sky.remove(); S.sky=null; }
  if(!S.sky){ S.sky=createGraphics(width,height); S.sky.pixelDensity(1); S.skyBufKey=width+'x'+height; }
  buildSky();
  S.skyKey=skyKey;
}

const nB = Math.max(1, Math.round(1 + P.density*6)); // 1..7 bolts
if(!S.bolts) S.bolts=[];
if(S.bolts.length!==nB || S.stU!==st || S.seedU!==P.seed){
  const restyle = (S.stU!==st);
  S.stU=st; S.seedU=P.seed;
  const arr=[];
  for(let i=0;i<nB;i++) arr.push(S.bolts[i]||{cyc:null, strokes:null, sx:0, sy:0});
  if(restyle) for(const b of arr){ b.cyc=null; b.strokes=null; }
  S.bolts=arr;
}

// ---- pass 1: advance each bolt's strike clock, (re)generate geometry, compute brightness ----
const boltB=new Array(nB);
let flashMax=0, fX=width/2, fY=0;
for(let i=0;i<nB;i++){
  const b=S.bolts[i];
  const rate=(0.20 + P.strike*0.85)*(0.55+P.speed*0.75)*(0.7+frb(i)*0.7)*(0.85+intn*0.4);
  const phase=K.t*rate + frb(i+50)*3.3;
  const cyc=Math.floor(phase);
  const frac=phase-Math.floor(phase);
  if(b.cyc!==cyc || !b.strokes){
    b.cyc=cyc;
    const z=(((P.seed+1)*2654435761) ^ (i*40503) ^ (Math.abs(cyc)*668265263))>>>0;
    const rnd=mul(z);
    let sx=((i+0.5)/nB)*width + (rnd()-0.5)*width*0.10;
    sx = sx*0.7 + (clp(P.x,0,1)*width)*0.3;
    const sy = -u*0.03;
    b.sx=sx; b.sy=sy;
    b.strokes=genBolt(rnd, sx, sy);
  }
  const env=Math.pow(1-frac,1.5);
  const buzz=(st==='crimson'?0.10:st==='ice-blue'?0.05:st==='toxic-green'?0.35:st==='blueprint'?0.0:0.08);
  const flick=(0.55-buzz*0.5)+(0.45+buzz*0.5)*Math.sin(K.t*(15+i*4+buzz*40)+i*1.7);
  const onset=frac<0.10?(1-frac/0.10)*0.7:0;
  let bb=clp(env*flick+onset, 0, 1.3);
  bb += A.bass*0.55*env + A.treble*0.25*env;
  boltB[i]=bb;
  if(bb>flashMax){ flashMax=bb; fX=b.sx; fY=height*0.30; }
}

// ---- draw ----
push();
// dim storm sky with slow cloud drift (continuous motion floor even between strikes)
if(P.alpha<100) tint(0,0,100,P.alpha);
const dsx=Math.sin(K.t*0.05)*u*0.012, dsy=Math.cos(K.t*0.04)*u*0.010;
image(S.sky, dsx-u*0.035, dsy-u*0.035, width+u*0.07, height+u*0.07);
if(P.alpha<100) noTint();

const E=(0.4+P.energy*0.95)*(0.8+intn*0.45);
const fp=boltPal();

// partial sky flash (localized, capped -> illuminates cloud without strobing)
if(st!=='blueprint' && flashMax>0.05){
  const dc=drawingContext; dc.save();
  const fa=clp(flashMax*E*0.24, 0, 0.30)*aMul;
  const rg=dc.createRadialGradient(fX,fY,u*0.02, fX,fY,u*0.72);
  rg.addColorStop(0,'hsla('+(fp.fH|0)+',55%,74%,'+fa.toFixed(3)+')');
  rg.addColorStop(0.6,'hsla('+(fp.fH|0)+',55%,70%,'+(fa*0.35).toFixed(3)+')');
  rg.addColorStop(1,'hsla('+(fp.fH|0)+',55%,70%,0)');
  dc.globalCompositeOperation='lighter'; dc.fillStyle=rg; dc.fillRect(0,0,width,height);
  dc.restore();
}

// bolts: two-pass (wide colored glow + near-white hot core), or flat schematic (blueprint)
const w=u*0.0045*(0.5+P.scale*0.8);
if(st!=='blueprint') blendMode(ADD);
noFill();
function poly(pts){ beginShape(); for(let q=0;q<pts.length;q++) vertex(pts[q][0],pts[q][1]); endShape(); }
for(let i=0;i<nB;i++){
  const bmag=boltB[i]; if(bmag<0.02) continue;
  const strokes=S.bolts[i].strokes; if(!strokes) continue;
  for(let s=0;s<strokes.length;s++){
    const str=strokes[s];
    const gf=1/(1+str.gen*0.6);
    const bb=clp(bmag*gf*E, 0, 1.5)*aMul;
    if(st==='blueprint'){
      stroke(fp.cH, fp.cS, 92, clp(24+bb*46,0,86));
      strokeWeight((1.0+0.9*P.scale)*gf);
      poly(str.pts);
    } else {
      strokeCap(ROUND);
      stroke(fp.gH, fp.gS, 100, clp(bb*26,0,55));               // wide dim glow
      strokeWeight(w*3.4*gf*fp.gw); poly(str.pts);
      stroke(fp.gH, fp.gS*0.65, 100, clp(bb*42,0,78));          // mid halo
      strokeWeight(w*1.5*gf*fp.gw); poly(str.pts);
      stroke(fp.cH, fp.cS, 100, clp(bb*78*fp.cb,0,96));         // near-white core
      strokeWeight(Math.max(0.6, w*0.55*gf)); poly(str.pts);
    }
  }
}
blendMode(BLEND);
drawingContext.shadowBlur=0;
pop();
blendMode(BLEND);
